html:
{%
	var info = (data.length && data[0].employee_info) || null;

	if (!info && filters.employee) {
		info = {};
		try {
			frappe.call({
				method: "frappe.client.get_value",
				args: {
					doctype: "Employee",
					filters: { name: filters.employee },
					fieldname: ["employee_name", "company", "department", "designation"]
				},
				async: false,
				callback: function(r) { info = r.message || {}; }
			});
		} catch (e) {
			info = {};
		}
	}
	info = info || {};

	var counts = { on_time: 0, late: 0, absent: 0, leave: 0, half_day: 0, holiday: 0 };

	var to_minutes = function(text) {
		var minutes = 0;
		String(text || "").split(" ").forEach(function(part) {
			var n = parseInt(part, 10);
			if (isNaN(n)) return;
			if (part.slice(-1) === "h") minutes += n * 60;
			else if (part.slice(-1) === "m") minutes += n;
		});
		return minutes;
	};

	var total_minutes = 0;

	for (var i = 0, l = data.length; i < l; i++) {
		var st = data[i].status || "";
		if (st === "On Time") counts.on_time++;
		else if (st.indexOf("Late") === 0) counts.late++;
		else if (st === "Absent") counts.absent++;
		else if (st === "On Leave") counts.leave++;
		else if (st === "Half Day") counts.half_day++;
		else if (st === "Holiday") counts.holiday++;

		total_minutes += to_minutes(data[i].work_hrs);
	}

	var format_minutes = function(minutes) {
		if (!minutes) return "0h";
		var h = Math.floor(minutes / 60);
		var m = minutes % 60;
		return (h ? h + "h" : "") + (h && m ? " " : "") + (m ? m + "m" : "");
	};

	var row_class = function(st) {
		if (st === "Absent") return "row-absent";
		if (st === "Holiday" || st === "On Leave") return "row-muted";
		return "";
	};

	var status_class = function(st) {
		if (st === "On Time") return "status-ok";
		if (st.indexOf("Late") === 0) return "status-late";
		if (st === "Absent") return "status-absent";
		return "status-other";
	};
%}

<style>
	.hr-report { font-size: 12px; color: #1f2933; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
	.hr-report table { width: 100%; border-collapse: collapse; }

	.hr-report .report-header { border-bottom: 2px solid #1f2933; margin-bottom: 10px; }
	.hr-report .report-header td { border: none; padding: 0 0 6px 0; vertical-align: bottom; }
	.hr-report .report-title { font-size: 20px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; }
	.hr-report .report-company { font-size: 12px; color: #52606d; margin-top: 2px; }
	.hr-report .report-period { text-align: right; font-size: 12px; color: #52606d; }
	.hr-report .report-period b { color: #1f2933; }

	.hr-report .info-table td { border: none; padding: 3px 8px 3px 0; vertical-align: top; }
	.hr-report .info-label { color: #52606d; width: 14%; }
	.hr-report .info-value { font-weight: 600; width: 36%; }

	.hr-report .summary-table { margin: 12px 0; border: 1px solid #cbd2d9; }
	.hr-report .summary-table td { width: 12.5%; text-align: center; padding: 7px 4px; border-right: 1px solid #cbd2d9; background: #f7f8fa; }
	.hr-report .summary-table td:last-child { border-right: none; }
	.hr-report .summary-value { display: block; font-size: 16px; font-weight: 700; }
	.hr-report .summary-label { display: block; font-size: 9px; letter-spacing: .5px; text-transform: uppercase; color: #52606d; }

	.hr-report .data-table thead { display: table-header-group; }
	.hr-report .data-table tr { page-break-inside: avoid; }
	.hr-report .data-table th {
		background: #cdcdcd;
		border: 1px solid #7e7e7e;
		padding: 6px 8px !important;
		font-size: 10px;
		letter-spacing: .5px;
		text-transform: uppercase;
		text-align: left;
		font-weight: bold;
		color: #000;
	}
	.hr-report .data-table td { border: 1px solid #cbd2d9; padding: 5px 8px !important; }
	.hr-report .data-table .text-center { text-align: center; }

	.hr-report .status-ok { color: #1f7a3d; font-weight: 600; }
	.hr-report .status-late { color: #b45309; font-weight: 600; }
	.hr-report .status-absent { color: #c81e1e; font-weight: 700; }
	.hr-report .status-other { color: #52606d; font-weight: 600; }
</style>

<div class="hr-report">

	<table class="report-header">
		<tr>
			<td>
				<div class="report-title">{%= __("Attendance Report") %}</div>
				{% if(info.company) { %}<div class="report-company">{%= info.company %}</div>{% } %}
			</td>
			<td class="report-period">
				{%= __("Period") %}<br>
				<b>{%= frappe.datetime.str_to_user(filters.from_date) %} &ndash; {%= frappe.datetime.str_to_user(filters.to_date) %}</b>
			</td>
		</tr>
	</table>

	<table class="info-table">
		<tr>
			<td class="info-label">{%= __("Employee ID") %}</td>
			<td class="info-value">{%= filters.employee %}</td>
			<td class="info-label">{%= __("Department") %}</td>
			<td class="info-value">{%= info.department || "" %}</td>
		</tr>
		<tr>
			<td class="info-label">{%= __("Employee Name") %}</td>
			<td class="info-value">{%= info.employee_name || "" %}</td>
			<td class="info-label">{%= __("Designation") %}</td>
			<td class="info-value">{%= info.designation || "" %}</td>
		</tr>
		{% if(filters.status) { %}
		<tr>
			<td class="info-label">{%= __("Status Filter") %}</td>
			<td class="info-value">{%= filters.status %}</td>
			<td></td>
			<td></td>
		</tr>
		{% } %}
	</table>

	<table class="summary-table">
		<tr>
			<td><span class="summary-value">{%= data.length %}</span><span class="summary-label">{%= __("Total Days") %}</span></td>
			<td><span class="summary-value">{%= counts.on_time %}</span><span class="summary-label">{%= __("On Time") %}</span></td>
			<td><span class="summary-value">{%= counts.late %}</span><span class="summary-label">{%= __("Late") %}</span></td>
			<td><span class="summary-value">{%= counts.absent %}</span><span class="summary-label">{%= __("Absent") %}</span></td>
			<td><span class="summary-value">{%= counts.leave %}</span><span class="summary-label">{%= __("On Leave") %}</span></td>
			<td><span class="summary-value">{%= counts.holiday %}</span><span class="summary-label">{%= __("Holiday") %}</span></td>
			<td><span class="summary-value">{%= format_minutes(total_minutes) %}</span><span class="summary-label">{%= __("Total Work Hrs") %}</span></td>
		</tr>
	</table>

	<table class="data-table">
		<thead>
			<tr>
				<th style="width: 5%">#</th>
				<th style="width: 14%">{%= __("Date") %}</th>
				<th style="width: 10%">{%= __("Day") %}</th>
				<th class="text-center" style="width: 15%">{%= __("In") %}</th>
				<th class="text-center" style="width: 15%">{%= __("Out") %}</th>
				<th class="text-center" style="width: 16%">{%= __("Work Hrs") %}</th>
				<th style="width: 25%">{%= __("Status") %}</th>
			</tr>
		</thead>
		<tbody>
			{% if(!data.length) { %}
				<tr>
					<td colspan="7" class="text-center">{%= __("No data") %}</td>
				</tr>
			{% } %}

			{% for(var i = 0, l = data.length; i < l; i++) { %}
				<tr class="{%= row_class(data[i].status || '') %}">
					<td>{%= i + 1 %}</td>
					<td>{%= data[i].date %}</td>
					<td>{%= data[i].day %}</td>
					<td class="text-center">{%= data[i].in_time || "" %}</td>
					<td class="text-center">{%= data[i].out_time || "" %}</td>
					<td class="text-center">{%= data[i].work_hrs || "" %}</td>
					<td class="{%= status_class(data[i].status || '') %}">{%= data[i].status %}</td>
				</tr>
			{% } %}
		</tbody>
	</table>
</div>
